SELECT FROM company_users c
c.company_name LIKE CONCAT('%', #{companyName}, '%')
AND c.status = #{status}
AND c.recall_status = #{recallStatus}
( FIND_IN_SET(#{tag}, REPLACE(c.company_tag, '双向选择阶段', '校企双向选择')) > 0 OR (#{tag} = '校企双向选择' AND c.audit_status = 1) OR (#{tag} = '接受兜底' AND (c.cooperation_mode LIKE '%兜底%' OR c.accept_backup = 1)) OR (#{tag} = '实习基地' AND c.is_internship_base = 1) OR (#{tag} = '已签协议' AND c.has_training_base_agreement = 1) OR (#{tag} = '校友单位' AND c.is_alumni_unit = 1) )
AND c.industry = #{industry}
AND ( c.company_name LIKE CONCAT('%', #{keyword}, '%') OR EXISTS ( SELECT 1 FROM company_school_liaison csl JOIN teacher_users liaison_teacher ON liaison_teacher.id = csl.teacher_id WHERE csl.company_id = c.id AND (liaison_teacher.name LIKE CONCAT('%', #{keyword}, '%') OR liaison_teacher.phone LIKE CONCAT('%', #{keyword}, '%')) ) OR EXISTS ( SELECT 1 FROM company_visit_record cvr_keyword JOIN company_visit_participant cvp_keyword ON cvp_keyword.visit_record_id = cvr_keyword.id JOIN teacher_users visit_teacher ON visit_teacher.id = cvp_keyword.teacher_id WHERE cvr_keyword.company_id = c.id AND visit_teacher.name LIKE CONCAT('%', #{keyword}, '%') ) OR EXISTS ( SELECT 1 FROM company_alumni_member cam WHERE cam.company_id = c.id AND cam.name LIKE CONCAT('%', #{keyword}, '%') ) )
AND EXISTS ( SELECT 1 FROM company_visit_record cvr_state WHERE cvr_state.company_id = c.id AND YEAR(cvr_state.visit_date) = #{visitedYear} )
AND NOT EXISTS ( SELECT 1 FROM company_visit_record cvr_state WHERE cvr_state.company_id = c.id AND YEAR(cvr_state.visit_date) = #{visitedYear} )
AND EXISTS ( SELECT 1 FROM company_visit_record cvr_teacher JOIN company_visit_participant cvp_teacher ON cvp_teacher.visit_record_id = cvr_teacher.id WHERE cvr_teacher.company_id = c.id AND cvp_teacher.teacher_id = #{visitTeacherId}
AND YEAR(cvr_teacher.visit_date) = #{visitedYear}
)
AND EXISTS ( SELECT 1 FROM company_school_liaison csl_filter WHERE csl_filter.company_id = c.id AND csl_filter.teacher_id = #{liaisonTeacherId} )
ORDER BY CASE WHEN c.recall_status = 1 THEN 0 WHEN c.status = 0 THEN 1 WHEN c.status = 1 THEN 2 ELSE 3 END, c.create_time DESC, c.id DESC

SELECT 
FROM company_users c
WHERE c.id = #{id}

SELECT * FROM company_users
WHERE recall_status = 1

    AND id = #{companyId}

ORDER BY recall_apply_time DESC
LIMIT #{offset}, #{pageSize}

