recall_audit_remark = #{recallAuditRemark},
audit_status = CASE WHEN #{recallStatus} = 2 THEN 3 WHEN #{recallStatus} = 3 THEN 0 ELSE audit_status END, update_time = NOW() WHERE id = #{id}

UPDATE company_users
cooperation_mode = #{cooperationMode}, contact_person = #{contactPerson}, contact_phone = #{contactPhone}, contact_email = #{contactEmail}, address = #{address}, city = #{city}, introduction = #{introduction}, credit_code = #{creditCode}, phone = #{phone}, email = #{email}, business_license = #{businessLicense}, legal_id_card = #{legalIdCard}, update_time = NOW()
WHERE id = #{id}

